-- An approved label plan never changes the physical evidence or its lifetime.
CREATE TABLE mapping_corrections(
 id varchar(32) PRIMARY KEY,
 project_id varchar(32) NOT NULL REFERENCES projects(id),
 asset_id varchar(32) NOT NULL REFERENCES project_assets(id),
 base_scope_hash char(64) NOT NULL CHECK(base_scope_hash ~ '^[0-9a-f]{64}$'),
 source_scope_hash char(64) NOT NULL CHECK(source_scope_hash ~ '^[0-9a-f]{64}$'),
 source_candidate jsonb NOT NULL,
 changes jsonb NOT NULL CHECK(jsonb_typeof(changes)='array' AND jsonb_array_length(changes) BETWEEN 1 AND 512),
 requested_by varchar(32) NOT NULL REFERENCES users(id),
 reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 3 AND 1000),
 created_at timestamptz NOT NULL,
 CHECK((source_candidate->>'project_id'=project_id AND source_candidate->>'asset_id'=asset_id AND source_candidate->>'scope_hash'=source_scope_hash AND source_candidate->>'base_scope_hash'=base_scope_hash) IS TRUE)
);
CREATE TABLE mapping_correction_decisions(
 correction_id varchar(32) PRIMARY KEY REFERENCES mapping_corrections(id),
 approved boolean NOT NULL,
 approved_by varchar(32) NOT NULL REFERENCES users(id),
 reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 3 AND 1000),
 created_at timestamptz NOT NULL
);
CREATE INDEX mapping_correction_history ON mapping_corrections(project_id,asset_id,created_at DESC,id DESC);
CREATE TRIGGER mapping_correction_immutable BEFORE UPDATE OR DELETE ON mapping_corrections FOR EACH ROW EXECUTE FUNCTION keel_exec_immutable();
CREATE TRIGGER mapping_correction_decision_immutable BEFORE UPDATE OR DELETE ON mapping_correction_decisions FOR EACH ROW EXECUTE FUNCTION keel_exec_immutable();
CREATE FUNCTION keel_mapping_correction_scope() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE proposal mapping_corrections; actor varchar; prior varchar; validate_plan boolean:=true;
BEGIN
 IF TG_TABLE_NAME='mapping_corrections' THEN proposal:=NEW; actor:=NEW.requested_by;
 ELSE SELECT * INTO proposal FROM mapping_corrections WHERE id=NEW.correction_id; actor:=NEW.approved_by; validate_plan:=NEW.approved; END IF;
 IF NOT EXISTS(SELECT 1 FROM project_assets a JOIN projects p ON p.id=a.project_id JOIN users u ON u.id=actor WHERE a.id=proposal.asset_id AND a.project_id=proposal.project_id AND p.state NOT IN('archived','delivered') AND u.enabled AND (u.is_admin OR EXISTS(SELECT 1 FROM memberships m WHERE m.user_id=u.id AND m.project_id=p.id AND m.role IN('Admin','DL')))) THEN RAISE EXCEPTION 'mapping correction requires mutable project and current DL authority'; END IF;
 IF validate_plan THEN
  IF NOT (keel_wiring_original_timestamp(proposal.source_candidate->>'valid_until')>clock_timestamp()) IS TRUE OR EXISTS(SELECT 1 FROM jsonb_array_elements(proposal.source_candidate->'conflicts') c WHERE c->>'code' NOT IN('MAPPING_LOGICAL_NAME_CONFLICT','MAPPING_BOM_NAME_INVALID')) THEN RAISE EXCEPTION 'label changes cannot waive physical failures or renew evidence'; END IF;
  IF jsonb_array_length(proposal.changes)<>jsonb_array_length(proposal.source_candidate->'bindings') OR (SELECT count(DISTINCT c->>'physical_port_id') FROM jsonb_array_elements(proposal.changes) c)<>jsonb_array_length(proposal.changes) OR (SELECT count(DISTINCT c->>'logical_name') FROM jsonb_array_elements(proposal.changes) c)<>jsonb_array_length(proposal.changes) OR EXISTS(SELECT 1 FROM jsonb_array_elements(proposal.changes) c WHERE NOT (c->>'logical_name' ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,62}$') IS TRUE OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(proposal.source_candidate->'bindings') b WHERE b#>>'{plan,physical_port_id}'=c->>'physical_port_id')) THEN RAISE EXCEPTION 'correction requires a full unique logical name plan over original physical ports'; END IF;
  SELECT c.id INTO prior FROM mapping_corrections c JOIN mapping_correction_decisions d ON d.correction_id=c.id AND d.approved WHERE c.project_id=proposal.project_id AND c.asset_id=proposal.asset_id AND c.base_scope_hash=proposal.base_scope_hash ORDER BY d.created_at DESC,c.id DESC LIMIT 1;
  IF coalesce(proposal.source_candidate->>'correction_id','') IS DISTINCT FROM coalesce(prior,'') THEN RAISE EXCEPTION 'mapping correction cannot overwrite a newer approval'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER mapping_correction_scope BEFORE INSERT ON mapping_corrections FOR EACH ROW EXECUTE FUNCTION keel_mapping_correction_scope();
CREATE TRIGGER mapping_correction_decision_scope BEFORE INSERT ON mapping_correction_decisions FOR EACH ROW EXECUTE FUNCTION keel_mapping_correction_scope();

CREATE OR REPLACE FUNCTION keel_mapping_scope() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE source mapping_assessments; frozen jsonb; binding jsonb; gpu jsonb; original jsonb; port_count integer; gpu_count integer; nic_count integer; prior varchar; correction mapping_corrections;
BEGIN
 IF TG_TABLE_NAME='mapping_assessments' THEN
  IF NOT EXISTS(SELECT 1 FROM project_assets a JOIN projects p ON p.id=a.project_id JOIN users u ON u.id=NEW.created_by WHERE a.id=NEW.asset_id AND a.project_id=NEW.project_id AND a.machine_id=NEW.machine_id AND p.state NOT IN('archived','delivered') AND u.enabled AND (u.is_admin OR EXISTS(SELECT 1 FROM memberships m WHERE m.user_id=u.id AND m.project_id=p.id AND m.role IN('Admin','DL')))) THEN RAISE EXCEPTION 'mapping assessment requires current project scope and DL authority'; END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO source FROM mapping_assessments WHERE id=NEW.assessment_id;
 frozen:=source.candidate;
 IF source.id IS NULL OR NEW.project_id IS DISTINCT FROM source.project_id OR NEW.asset_id IS DISTINCT FROM source.asset_id OR NEW.machine_id IS DISTINCT FROM source.machine_id OR NEW.confirmed_by IS DISTINCT FROM source.created_by OR NOT (frozen->>'ready'='true' AND frozen->>'verdict'='PASS' AND jsonb_array_length(frozen->'conflicts')=0 AND keel_wiring_original_timestamp(frozen->>'valid_until')>clock_timestamp()) IS TRUE THEN RAISE EXCEPTION 'mapping revision requires a fresh complete passing assessment'; END IF;
 SELECT id INTO prior FROM mapping_revisions WHERE project_id=NEW.project_id AND asset_id=NEW.asset_id ORDER BY version DESC LIMIT 1;
 IF NEW.previous_id IS DISTINCT FROM prior OR NEW.version<>coalesce((SELECT max(version)+1 FROM mapping_revisions WHERE project_id=NEW.project_id AND asset_id=NEW.asset_id),1) THEN RAISE EXCEPTION 'mapping versions must retain the original immutable history'; END IF;
 IF NOT EXISTS(SELECT 1 FROM project_assets asset JOIN pci_topology_snapshots topology ON topology.asset_id=asset.id AND topology.project_id=asset.project_id JOIN validation_precollect_requests request ON request.id=topology.precollect_id JOIN device_model_versions model ON model.id=topology.model_version_id JOIN users u ON u.id=NEW.confirmed_by WHERE asset.id=NEW.asset_id AND asset.project_id=NEW.project_id AND asset.machine_id=NEW.machine_id AND asset.state IN('lldp','mapped','configured','netverified','tested') AND asset.model_version_id=frozen->>'model_version_id' AND asset.version=(frozen->>'asset_version')::bigint AND topology.id=frozen->>'topology_id' AND topology.g1_id=frozen->>'g1_id' AND topology.model_version_id=asset.model_version_id AND model.content_hash=frozen->>'model_content_hash' AND topology.verdict='PASS' AND topology.origin='real' AND topology.valid_until>=keel_wiring_original_timestamp(frozen->>'valid_until') AND request.scope->>'bom_package_id'=frozen->>'bom_package_id' AND u.enabled AND (u.is_admin OR EXISTS(SELECT 1 FROM memberships m WHERE m.user_id=u.id AND m.project_id=asset.project_id AND m.role IN('Admin','DL')))) THEN RAISE EXCEPTION 'mapping must consume the current independent real model and topology'; END IF;
 IF EXISTS(SELECT 1 FROM topology_issue_bindings b JOIN issues i ON i.id=b.issue_id WHERE b.project_id=NEW.project_id AND b.asset_id=NEW.asset_id AND b.origin='real' AND i.state<>'closed') OR EXISTS(SELECT 1 FROM validation_wiring_issue_bindings b JOIN issues i ON i.id=b.issue_id WHERE b.project_id=NEW.project_id AND b.asset_id=NEW.asset_id AND b.host_origin='real' AND b.switch_origin='device' AND i.state<>'closed' AND EXISTS(SELECT 1 FROM jsonb_array_elements(frozen->'bindings') p WHERE p#>>'{plan,physical_port_id}'=b.physical_port_id)) THEN RAISE EXCEPTION 'mapping cannot bypass unresolved real topology or wiring issues'; END IF;
 SELECT count(*),count(DISTINCT c.id) INTO port_count,nic_count FROM physical_ports p JOIN components c ON c.id=p.parent_uid AND c.category='nic' JOIN bom_items i ON i.item_uid=p.id AND i.status<>'retired' JOIN bom_items parent ON parent.item_uid=c.id AND parent.status<>'retired' JOIN bom_item_revisions r ON r.item_uid=p.id AND r.project_id=NEW.project_id AND r.package_id=frozen->>'bom_package_id' WHERE p.machine_id=NEW.machine_id AND coalesce(r.row_snapshot#>>'{values,port_role}','')<>'unused';
 SELECT count(*) INTO gpu_count FROM validation_precollect_requests q JOIN pci_topology_snapshots t ON t.precollect_id=q.id CROSS JOIN LATERAL jsonb_array_elements(q.scope->'components') c WHERE t.id=frozen->>'topology_id' AND c->>'category'='gpu';
 IF NOT (port_count>0 AND jsonb_array_length(frozen->'bindings')=port_count AND (frozen#>>'{coverage,required_ports}')::int=port_count AND (frozen#>>'{coverage,mapped_ports}')::int=port_count AND (frozen#>>'{coverage,required_nics}')::int=nic_count AND (frozen#>>'{coverage,mapped_nics}')::int=nic_count AND (frozen#>>'{coverage,required_gpus}')::int=gpu_count AND (frozen#>>'{coverage,mapped_gpus}')::int=gpu_count) IS TRUE THEN RAISE EXCEPTION 'mapping coverage cannot shrink the enabled GPU/NIC/port denominator'; END IF;
 IF (SELECT count(DISTINCT b#>>'{plan,physical_port_id}') FROM jsonb_array_elements(frozen->'bindings') b)<>port_count OR (SELECT count(DISTINCT b->>'logical_name') FROM jsonb_array_elements(frozen->'bindings') b)<>port_count OR (SELECT count(DISTINCT b#>>'{observed,interface}') FROM jsonb_array_elements(frozen->'bindings') b)<>port_count OR (SELECT count(DISTINCT b#>>'{observed,permanent_mac}') FROM jsonb_array_elements(frozen->'bindings') b)<>port_count OR (SELECT count(DISTINCT b->>'switch_port_id') FROM jsonb_array_elements(frozen->'bindings') b)<>port_count THEN RAISE EXCEPTION 'mapping contains conflicting stable identities or logical names'; END IF;


 IF (SELECT count(*) FROM physical_ports p JOIN components c ON c.id=p.parent_uid AND c.category='nic' JOIN bom_items i ON i.item_uid=p.id AND i.status<>'retired' JOIN bom_items parent ON parent.item_uid=c.id AND parent.status<>'retired' JOIN bom_item_revisions r ON r.item_uid=p.id AND r.project_id=NEW.project_id AND r.package_id=frozen->>'bom_package_id' WHERE p.machine_id=NEW.machine_id AND r.row_snapshot#>>'{values,port_role}'='unused')<>jsonb_array_length(coalesce(frozen->'excluded_ports','[]'::jsonb)) OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(frozen->'excluded_ports','[]'::jsonb)) excluded WHERE excluded->>'reason' IS DISTINCT FROM 'not_applicable_bom_unused' OR excluded#>>'{plan,role}' IS DISTINCT FROM 'unused' OR NOT EXISTS(SELECT 1 FROM physical_ports p JOIN components c ON c.id=p.parent_uid JOIN bom_item_revisions r ON r.item_uid=p.id AND r.project_id=NEW.project_id AND r.package_id=frozen->>'bom_package_id' WHERE p.machine_id=NEW.machine_id AND p.id=excluded#>>'{plan,physical_port_id}' AND c.id=excluded#>>'{plan,component_id}' AND r.row_snapshot#>>'{values,port_role}'='unused')) THEN RAISE EXCEPTION 'not-applicable ports must retain the explicit frozen unused BOM role'; END IF;
 IF coalesce(frozen->>'correction_id','')<>'' THEN
  SELECT c.* INTO correction FROM mapping_corrections c JOIN mapping_correction_decisions d ON d.correction_id=c.id AND d.approved WHERE c.id=frozen->>'correction_id' AND c.project_id=NEW.project_id AND c.asset_id=NEW.asset_id AND c.base_scope_hash=frozen->>'base_scope_hash';
  IF correction.id IS NULL OR correction.id IS DISTINCT FROM (SELECT c.id FROM mapping_corrections c JOIN mapping_correction_decisions d ON d.correction_id=c.id AND d.approved WHERE c.project_id=NEW.project_id AND c.asset_id=NEW.asset_id AND c.base_scope_hash=frozen->>'base_scope_hash' ORDER BY d.created_at DESC,c.id DESC LIMIT 1) THEN RAISE EXCEPTION 'mapping publication requires the current approved correction for its exact base'; END IF;
  IF (frozen-'bindings'-'conflicts'-'ready'-'verdict'-'scope_hash'-'correction_id') IS DISTINCT FROM (correction.source_candidate-'bindings'-'conflicts'-'ready'-'verdict'-'scope_hash'-'correction_id') OR jsonb_array_length(frozen->'bindings')<>jsonb_array_length(correction.source_candidate->'bindings') OR EXISTS(SELECT 1 FROM jsonb_array_elements(frozen->'bindings') b WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(correction.source_candidate->'bindings') original WHERE (original-'logical_name')=(b-'logical_name'))) THEN RAISE EXCEPTION 'approved logical corrections cannot replace physical evidence, role plans or validity'; END IF;
 END IF;
 FOR binding IN SELECT value FROM jsonb_array_elements(frozen->'bindings') LOOP
  IF NOT EXISTS(SELECT 1 FROM physical_ports p JOIN components c ON c.id=p.parent_uid AND c.category='nic' JOIN bom_item_revisions r ON r.item_uid=p.id AND r.project_id=NEW.project_id AND r.package_id=frozen->>'bom_package_id' JOIN validation_wiring_confirmed_ports confirmed ON confirmed.physical_port_id=p.id JOIN validation_wiring_confirmations g ON g.id=confirmed.confirmation_id JOIN validation_wiring_step_reports three ON three.id=g.step3_id JOIN validation_wiring_step_reports two ON two.id=three.parent_id JOIN validation_wiring_batch_targets target ON target.batch_id=g.batch_id AND target.asset_id=g.asset_id WHERE p.id=binding#>>'{plan,physical_port_id}' AND p.machine_id=NEW.machine_id AND c.id=binding#>>'{plan,component_id}' AND coalesce(c.serial_number,'')=binding#>>'{plan,component_serial}' AND r.row_snapshot#>>'{values,port_index}'=binding#>>'{plan,port_index}' AND r.row_snapshot#>>'{values,port_role}'=binding#>>'{plan,role}' AND binding#>>'{plan,role}' IN('management','storage','compute','oob') AND coalesce(r.row_snapshot#>>'{values,rail}','')=binding#>>'{plan,rail}' AND g.id=binding->>'confirmation_id' AND g.project_id=NEW.project_id AND g.asset_id=NEW.asset_id AND g.valid_until>=keel_wiring_original_timestamp(frozen->>'valid_until') AND confirmed.expected=binding->'observed' AND confirmed.switch_port_id=binding->>'switch_port_id' AND confirmed.expected->>'physical_port_id'=p.id AND confirmed.expected->>'component_id'=c.id AND confirmed.expected->>'rail'=binding#>>'{plan,rail}' AND confirmed.expected->>'port_index'=binding#>>'{plan,port_index}' AND coalesce(r.row_snapshot#>>'{values,port_name}','')=binding#>>'{plan,name}' AND ((correction.id IS NULL AND binding->>'logical_name'=CASE WHEN coalesce(r.row_snapshot#>>'{values,port_name}','')<>'' THEN r.row_snapshot#>>'{values,port_name}' ELSE 'nic-'||coalesce(nullif(r.row_snapshot#>>'{values,rail}',''),r.row_snapshot#>>'{values,port_role}')||'-p'||(r.row_snapshot#>>'{values,port_index}') END) OR (correction.id IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(correction.changes) change WHERE change->>'physical_port_id'=p.id AND change->>'logical_name'=binding->>'logical_name'))) AND binding->>'logical_name' ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,62}$' AND three.verdict='PASS' AND two.verdict='PASS' AND target.topology_id=frozen->>'topology_id' AND NOT EXISTS(SELECT 1 FROM validation_wiring_step_reports newer WHERE newer.batch_id=three.batch_id AND newer.asset_id=three.asset_id AND ((newer.step=3 AND newer.version>three.version) OR (newer.step=2 AND newer.version>two.version))) AND NOT EXISTS(SELECT 1 FROM validation_wiring_confirmed_ports next_port JOIN validation_wiring_confirmations next_g ON next_g.id=next_port.confirmation_id WHERE next_g.project_id=g.project_id AND next_g.asset_id=g.asset_id AND next_port.physical_port_id=p.id AND (next_g.created_at,next_g.id)>(g.created_at,g.id))) THEN RAISE EXCEPTION 'mapping binding must retain exact BOM identities and current G2 physical endpoints'; END IF;
  IF binding#>>'{plan,role}'='compute' AND jsonb_array_length(binding->'gpus')=0 THEN RAISE EXCEPTION 'enabled compute ports require independent GPU relations'; END IF;
  FOR gpu IN SELECT value FROM jsonb_array_elements(binding->'gpus') LOOP
   IF NOT EXISTS(SELECT 1 FROM validation_wiring_confirmations g JOIN validation_wiring_batch_targets target ON target.batch_id=g.batch_id AND target.asset_id=g.asset_id CROSS JOIN LATERAL jsonb_array_elements(target.relations->'rows') r WHERE g.id=binding->>'confirmation_id' AND target.topology_id=frozen->>'topology_id' AND r->>'verdict'='PASS' AND r->>'physical_port_id'=binding#>>'{plan,physical_port_id}' AND r->>'nic_component_id'=binding#>>'{plan,component_id}' AND r->>'gpu_component_id'=gpu->>'component_id' AND r->>'gpu_key'=gpu->>'model_key' AND r->>'gpu_uuid'=gpu->>'uuid' AND r#>>'{gpu_node,bdf}'=gpu->>'bdf' AND r#>>'{nic_node,bdf}'=binding#>>'{observed,bdf}' AND r->>'expected_affinity'=gpu->>'affinity' AND r->>'observed_affinity'=r->>'expected_affinity' AND r->>'computed_affinity'=r->>'expected_affinity') THEN RAISE EXCEPTION 'GPU/NIC relations must originate from the independent Step 1 model comparison'; END IF;
  END LOOP;
 END LOOP;
 IF (SELECT count(DISTINCT gpu->>'component_id') FROM jsonb_array_elements(frozen->'bindings') b CROSS JOIN LATERAL jsonb_array_elements(b->'gpus') gpu)<>gpu_count THEN RAISE EXCEPTION 'every enabled GPU must be mapped'; END IF;
 RETURN NEW;
END $$;
